#[cfg(test)]
mod tests {
    use std::time::Duration;

    use chrono::Utc;
    use rigorix_engine::capacity_ledger::domain::{
        IdempotencyKey, Lease, Reservation, ReservationId, ReservationState, ResourceId,
    };

    fn reservation() -> Reservation {
        Reservation::new(
            ReservationId::new(),
            ResourceId::new("gpu"),
            3,
            Lease::expiring_in(Utc::now(), Duration::from_secs(60)),
            IdempotencyKey::new("k1"),
        )
    }

    #[test]
    fn test_reservation_is_defined() {
        let r = reservation();
        assert_eq!(r.state, ReservationState::Outstanding);
        assert!(!r.is_terminal());
        assert_eq!(r.amount, 3);
        assert_eq!(r.idempotency_key, IdempotencyKey::new("k1"));
    }

    #[test]
    fn test_reservation_interacts_with_resource() {
        let r = reservation();
        assert_eq!(r.resource, ResourceId::new("gpu"));

        // Exactly one terminal transition: all non-outstanding states are terminal.
        assert!(ReservationState::Committed.is_terminal());
        assert!(ReservationState::Released.is_terminal());
        assert!(ReservationState::Expired.is_terminal());

        let now = Utc::now();
        let lease = Lease::expiring_in(now, Duration::from_secs(30));
        assert!(!lease.is_expired_at(now));
        assert!(lease.is_expired_at(now + chrono::Duration::seconds(60)));
    }
}
